catalog_script_client.script:
function onLoad() {
    g_form.setValue('current_section', 1);
    g_form.setDisplay('current_section', false);
    //Section 1
    g_form.setDisplay('geo', true);
    g_form.setDisplay('company', true);
    //Section 2
    g_form.setDisplay('province', false);
    g_form.setDisplay('city', false);
    g_form.setDisplay('address', false);
    //Section 3
    g_form.setDisplay('postal_code', false);
    //Section 4
    g_form.setDisplay('comment', false);
    //Section 5
    g_form.setDisplay('requested_by', false);
    g_form.setDisplay('alternate_buyer', false);
    g_form.setDisplay('first_payment_approver_display', false);
    //mandatory
    // g_form.setMandatory('alternate_buyer', false);
    // g_form.setMandatory('first_payment_approver_display', false);
}
